  p=new User();skill(p,3);intrinsic(p,9,25,0);SkillService.gI().affterUseSkill(p,3);check(System.currentTimeMillis()-p.playerSkill.skillSelect.lastTimeUseThisSkill<1000,"Masenko damage intrinsic does not shorten cooldown");
