  rates(null,null);ef.set(null,Map.of("mob_rewards",true,"hung_vuong",true,"trung_thu",true,"october20",true));p=new User();p.nPoint.tlLuck=15;
  for(String cat:List.of("dragon_ball","upgrade_stone","food","porata","shop","crystal","capsule","hung_vuong","trung_thu","october20"))near(MobDropBonuses.chance(p,cat,"test",2,100),2.3,"luck applies to random category "+cat);
  p.nPoint.tlLuck=1900;check(nro.models.event.EventDrops.rollMaterials(1,false,p).size()==6,"actual Hung Vuong cooking ingredients use owner luck");check(nro.models.event.EventDrops.rollMaterials(nro.models.consts.ConstMob.MOC_NHAN,false,p).isEmpty(),"luck cannot enable ingredients on training dummy");
